contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into c before attempting withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // require the test contract has enough ETH to deposit and that depositAmount > 0
        require(depositAmount > 0 && address(this).balance >= depositAmount);

        // perform deposit into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record contract balance after deposit
        uint beforeCBalance = address(c).balance;

        // call withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCBalance = address(c).balance;

        // If withdrawAll did not revert, then contract balance must have decreased by at least depositAmount.
        // If it reverted, no condition on balances is required here.
        assert(reverted || beforeCBalance - afterCBalance >= depositAmount);
    }

    // accept Ether if withdrawAll sends Ether back
    receive() external payable {}
}

